import type { Mat4 } from '../math/types';

/**
 * One instance of an object generated by a collection instance or a particle system. Instances are
 * cached between evaluations: treat them (and their matrices) as immutable.
 */
export interface EvaluatedInstance {
  /**
   * Stable id: `${ownerId}:${sourceId}` for collection instances, `${ownerId}:${systemId}:${particle}`
   * for particles (plus `:${memberId}` for whole collections); nested instances append the id of the
   * inner instance.
   */
  id: string;
  /** Object generating the instance (instancing empty or particle emitter). */
  ownerId: string;
  /** Evaluated object whose geometry and materials are instanced. */
  sourceId: string;
  /** Final world matrix of the instance. */
  matrix: Mat4;
}
